CREATE TABLE IF NOT EXISTS ledger_accounts (id TEXT PRIMARY KEY, client_id TEXT, code TEXT NOT NULL, name TEXT NOT NULL, account_type TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(client_id, code));
CREATE TABLE IF NOT EXISTS journal_entries (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), entry_date TEXT NOT NULL, description TEXT NOT NULL, document_id TEXT, bank_transaction_id TEXT, book_number TEXT NOT NULL, vat_code TEXT, status TEXT NOT NULL, source TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), approved_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS journal_lines (id TEXT PRIMARY KEY, journal_entry_id TEXT NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE, ledger_account_id TEXT NOT NULL REFERENCES ledger_accounts(id), debit_cents INTEGER NOT NULL DEFAULT 0 CHECK(debit_cents >= 0), credit_cents INTEGER NOT NULL DEFAULT 0 CHECK(credit_cents >= 0), CHECK((debit_cents = 0) <> (credit_cents = 0)));
CREATE TABLE IF NOT EXISTS bank_accounts (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), iban TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bank_transactions (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), bank_account_id TEXT NOT NULL REFERENCES bank_accounts(id), transaction_date TEXT NOT NULL, description TEXT NOT NULL, counterparty TEXT, amount_cents INTEGER NOT NULL, status TEXT NOT NULL, document_id TEXT, journal_entry_id TEXT REFERENCES journal_entries(id));
CREATE TABLE IF NOT EXISTS purchase_invoices (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), supplier TEXT NOT NULL, invoice_number TEXT NOT NULL, invoice_date TEXT NOT NULL, due_date TEXT, net_cents INTEGER NOT NULL, vat_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, status TEXT NOT NULL, payment_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sales_invoices (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), debtor TEXT NOT NULL, invoice_number TEXT NOT NULL, invoice_date TEXT NOT NULL, due_date TEXT, net_cents INTEGER NOT NULL, vat_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, status TEXT NOT NULL, payment_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoice_lines (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, description TEXT NOT NULL, quantity REAL NOT NULL, unit_price_cents INTEGER NOT NULL, vat_code_id TEXT);
CREATE TABLE IF NOT EXISTS debtors (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), name TEXT NOT NULL, balance_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS creditors (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), name TEXT NOT NULL, balance_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS vat_codes (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, label TEXT NOT NULL, percentage REAL NOT NULL, direction TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounting_periods (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, closed_by TEXT, closed_at TEXT);
CREATE TABLE IF NOT EXISTS document_links (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id), document_id TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_rules (id TEXT PRIMARY KEY, client_id TEXT REFERENCES clients(id), supplier TEXT, description_contains TEXT, ledger_account_id TEXT REFERENCES ledger_accounts(id), vat_code_id TEXT REFERENCES vat_codes(id), profile_condition TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_journal_entries_client_date ON journal_entries(client_id, entry_date);
CREATE INDEX IF NOT EXISTS idx_bank_transactions_client_status ON bank_transactions(client_id, status);
CREATE INDEX IF NOT EXISTS idx_purchase_invoices_client_status ON purchase_invoices(client_id, status);
CREATE INDEX IF NOT EXISTS idx_sales_invoices_client_status ON sales_invoices(client_id, status);
CREATE INDEX IF NOT EXISTS idx_accounting_periods_client_dates ON accounting_periods(client_id, starts_at, ends_at);
PRAGMA optimize;
